#!/usr/bin/env bash
# Run all cases generated by generate.py, N_JOBS simulations in parallel (one OpenMP thread each).
# Usage: ./run_all.sh [runs directory] [filter substring]
set -u
RUNS=${1:-$(dirname "$0")/runs}
FILTER=${2:-}
N_JOBS=${N_JOBS:-4}
DAMASK_GRID=${DAMASK_GRID:-damask_grid}
export OMP_NUM_THREADS=${OMP_NUM_THREADS:-1}

run() {
  cd "$1" || exit 1
  [ -f job.done ] && exit 0
  "$DAMASK_GRID" -l load.yaml -g geom.vti -m material.yaml -n numerics.yaml -j job > log.txt 2>&1 \
    && touch job.done || echo "FAILED: $1"
}
export -f run
export DAMASK_GRID

# most expensive cases first
ls -d "$RUNS"/*"$FILTER"* | awk '{c=0; if ($0~/grad/) c+=100; if ($0~/_d5_/) c+=50; if ($0~/_d10_/) c+=20;
                                   if ($0~/noFlux/) c-=40; print c, $0}' | sort -rn | cut -d' ' -f2- \
  | xargs -P "$N_JOBS" -I{} bash -c 'run {}'
